import { watchDom } from '../../core/observer';
import { create } from '../../utils/dom';
import { runIconEngine } from '../../utils/icons';
import { startPtvIconEngine } from '../icons';

const HEADER_LOGO_URL = '/assets/logo/banner-light.png';

function enhanceHeaderIcons() {
    const header = document.querySelector('.ptv-legacy-skinHeader, .skinHeader');
    const headerLeft = header?.querySelector('.headerLeft');

    if (headerLeft && !headerLeft.querySelector('.ptv-stock-header-logo')) {
        const logo = create('a', {
            className: 'ptv-stock-header-logo itemAction',
            attrs: {
                href: '#/home',
                'data-action': 'link',
                'aria-label': 'Go to home'
            }
        });
        logo.appendChild(create('img', {
            attrs: {
                src: HEADER_LOGO_URL,
                alt: 'PiggieTV',
                loading: 'eager',
                decoding: 'async'
            }
        }));
        headerLeft.appendChild(logo);
    }

    if (!header) return;

    header
        .querySelectorAll('button, .headerButton')
        .forEach(button => {
            button.classList.add('ptv-header-stock-button');
        });

    runIconEngine(header);
}

watchDom(enhanceHeaderIcons);
window.addEventListener('hashchange', enhanceHeaderIcons);
window.addEventListener('popstate', enhanceHeaderIcons);
startPtvIconEngine();
enhanceHeaderIcons();
